from collections import defaultdict

normal = {}
try:
    print(normal['x'])
except KeyError:
    print('KeyError')

data = defaultdict(int)
print(data['x'])
print(data)

numbers = [10, 20, 30, 40]
print(numbers[2])

values = {10, 20, 30, 40}
print(30 in values)

data = {'name': 'Aman', 'age': 25}
print(data['age'])
